// Computer-side tests (pio test -e native -f test_geom) of the chassis envelope check: WKB surface, AreaIndex,
// TrajectoryEnvelope, FollowObstacleGuard. Cases of the Kotlin tests (TrajectoryEnvelopeTest, AreaIndexTest,
// FollowObstacleGuardTest) with the same values; surfaces and reference results produced by JTS 1.20
// (geom_reference.h, generated by gen/Gen.java).
#include <unity.h>

